    // Yeni paylaşımı ekle
    existingShares.push(galleryData);

    // Güncellenmiş paylaşımları kaydet
    localStorage.setItem('auralize_shared_auras', JSON.stringify(existingShares));

    // Aurayı paylaşıldı olarak işaretle
