// Aura Data Service
// Bu dosya, local/auraDataService.ts'yi dışa aktarmaktadır

import { v4 as uuidv4 } from 'uuid';

// Aura veri modeli
export interface AuraData {
  auraType: string;
  story: string;
  strengths: string;
  potential: string;
  thinkingStyle: string;
  auraTitle: string;
  answers: { [key: number]: string };
}

// Aura sonucu
export interface AuraResult {
  id: string;
  auraType: string;
  auraTitle: string;
  story: string;
  strengths: string;
  potential: string;
  thinkingStyle: string;
  timestamp: number;
  answers: { [key: number]: string };
}

// Aura hikayesi
export interface AuraStory {
  id: string;
  userId: string;
  username: string;
  auraType: string;
  title: string;
  createdAt: Date;
  story: string;
  strengths: string;
  potential: string;
  thinkingStyle: string;
  auraTitle: string;
  isShared: boolean;
}

// Aura hikayesi kaydetme fonksiyonu
export const saveAuraStory = async (userId: string, auraData: any): Promise<void> => {
  try {
    console.log('[STORAGE] Aura verisi kaydediliyor...');

    // Veriyi kaydedilmeye hazırla
    const auraKey = `auralize_aura_${userId}_${Date.now()}`;

    // Trimlenmiş veri - saklama alanı kullanımını sınırlamak için boyutları sınırla
    const trimmedData = {
      auraType: auraData.auraType,
      timestamp: Date.now(),
      auraTitle: auraData.auraTitle || '',
      // Hikaye ve içgörüleri kısalt (çok uzunsa)
      story: auraData.story ? auraData.story.substring(0, 2000) : '',
      strengths: auraData.strengths ? auraData.strengths.substring(0, 500) : '',
      potential: auraData.potential ? auraData.potential.substring(0, 500) : '',
      thinkingStyle: auraData.thinkingStyle ? auraData.thinkingStyle.substring(0, 500) : '',
      // Cevapları da saklayalım, ancak bazı çalışma ortamları bunu kaldırabilir
      answers: auraData.answers || {}
    };

    try {
      // Mevcut depolama kullanımını kontrol et (opsiyonel)
      const localStorageUsed = JSON.stringify(localStorage).length;
      const maxAvailableStorage = 5 * 1024 * 1024; // 5MB - tahmini değer

      console.log(`[STORAGE] Mevcut localStorage kullanımı: ~${Math.round(localStorageUsed / 1024)} KB / ${Math.round(maxAvailableStorage / 1024)} KB`);

      if (localStorageUsed > maxAvailableStorage * 0.9) {
        console.warn('[STORAGE] localStorage neredeyse dolu! Bazı eski veriler temizleniyor...');

        // Eski aura verilerini temizle
        const keys = Object.keys(localStorage);
        const auraKeys = keys.filter(key => key.startsWith('auralize_aura_'));

        // Sıralama: en eskiden en yeniye
        auraKeys.sort((a, b) => {
          const timeA = Number(a.split('_').pop()) || 0;
          const timeB = Number(b.split('_').pop()) || 0;
          return timeA - timeB;
        });

        // En eski %30'u sil
        const keysToRemove = auraKeys.slice(0, Math.max(1, Math.floor(auraKeys.length * 0.3)));
        keysToRemove.forEach(key => {
          localStorage.removeItem(key);
          console.log(`[STORAGE] Eski aura verisi silindi: ${key}`);
        });
      }
    } catch (storageError) {
      console.warn('[STORAGE] localStorage kullanım kontrolü sırasında hata:', storageError);
    }

    // Küçültülmüş veriyi sakla
    try {
      localStorage.setItem(auraKey, JSON.stringify(trimmedData));
    } catch (quotaError) {
      console.error('[STORAGE] localStorage kotası aşıldı, acil temizlik yapılıyor');

      // Acil temizlik - localStorage'dan auralize ile ilgili eski verileri temizle
      const keys = Object.keys(localStorage);
      const auraKeys = keys.filter(key => key.startsWith('auralize_'));

      // En eski 20 öğeyi sil
      auraKeys.sort((a, b) => {
        const timeA = Number(a.split('_').pop()) || 0;
        const timeB = Number(b.split('_').pop()) || 0;
        return timeA - timeB;
      });

      const keysToRemove = auraKeys.slice(0, Math.min(20, auraKeys.length));
      keysToRemove.forEach(key => {
        localStorage.removeItem(key);
        console.log(`[STORAGE] Acil temizlik: Silinen veri: ${key}`);
      });

      // Tekrar kaydetmeyi dene
      localStorage.setItem(auraKey, JSON.stringify(trimmedData));
    }

    // En son aura verisini de sakla - her kullanıcı için en güncel aura verisi
    const latestKey = `auralize_user_${userId}_latest`;
    localStorage.setItem(latestKey, JSON.stringify(trimmedData));

    console.log('[STORAGE] Aura verisi başarıyla kaydedildi');
  } catch (error) {
    console.error('Aura kaydedilirken hata oluştu:', error);

    // Kritik hata durumunda bile kullanıcıya bir yanıt verebilmek için
    try {
      // Sadece temel veriyi kaydetmeyi dene
      const minimalData = {
        auraType: auraData.auraType,
        timestamp: Date.now(),
        auraTitle: auraData.auraTitle || '',
      };

      const latestKey = `auralize_user_${userId}_latest`;
      localStorage.setItem(latestKey, JSON.stringify(minimalData));
      console.log('[STORAGE] Minimum aura verisi kaydedildi');
    } catch (criticalError) {
      console.error('[STORAGE] Kritik hata! Minimum veri bile kaydedilemedi:', criticalError);
      throw new Error('Aura kaydedilemedi');
    }
  }
};

// Aura verisini getirme
export const getAuraStory = async (userId: string, auraId: string): Promise<AuraStory | null> => {
  try {
    // localStorage'dan kontrol et
    const localData = localStorage.getItem(`auralize_aura_${auraId}`);
    if (localData) {
      const parsedData = JSON.parse(localData);
      return {
        ...parsedData,
        createdAt: new Date(parsedData.createdAt || Date.now()),
        auraType: parsedData.auraType || 'creative', // Eğer auraType undefined ise varsayılan değer ata
        isShared: parsedData.isShared || false,
        title: parsedData.title || parsedData.auraTitle || 'Aura'
      };
    }

    // Kullanıcının tüm auralarını getir
    const allAuras = await getUserAuras(userId);
    const aura = allAuras.find(a => a.id === auraId);

    if (aura) {
      return {
        id: aura.id,
        userId,
        username: 'Kullanıcı',
        auraType: aura.auraType,
        title: aura.auraTitle,
        createdAt: new Date(aura.timestamp),
        story: aura.story,
        strengths: aura.strengths,
        potential: aura.potential,
        thinkingStyle: aura.thinkingStyle,
        auraTitle: aura.auraTitle,
        isShared: false
      };
    }

    // Bulunamadı
    return null;
  } catch (error) {
    console.error('[AuraDataService] Aura alınırken hata:', error);
    return null;
  }
};

// Kullanıcının tüm auralarını getirme
export const getUserAuras = async (userId: string): Promise<AuraResult[]> => {
  try {
    const auraStorageKey = `auralize_user_auras_${userId}`;
    const aurasJson = localStorage.getItem(auraStorageKey);

    if (!aurasJson) {
      return [];
    }

    const auras: AuraResult[] = JSON.parse(aurasJson);
    // Tarihe göre sırala (en yeniden en eskiye)
    return auras.sort((a, b) => b.timestamp - a.timestamp);
  } catch (error) {
    console.error('Kullanıcı auraları getirilirken hata:', error);
    return [];
  }
};

// ID'ye göre bir aura getirme
export const getAuraById = async (userId: string, auraId: string): Promise<AuraResult | null> => {
  try {
    const allAuras = await getUserAuras(userId);
    const aura = allAuras.find(a => a.id === auraId);
    return aura || null;
  } catch (error) {
    console.error('Aura getirilirken hata:', error);
    return null;
  }
};

// Aurayı paylaşım için galeriye ekleme
export const shareAuraToGallery = async (
  userId: string,
  auraId: string,
  description: string = '',
  hashtags: string[] = []
): Promise<boolean> => {
  try {
    // Aura verisini al
    const auraData = await getAuraStory(userId, auraId);

    if (!auraData) {
      console.error('[AuraDataService] Paylaşılacak aura bulunamadı');
      return false;
    }

    // auraType kontrolü
    const auraType = auraData.auraType || 'creative'; // Eğer auraType undefined ise varsayılan değer ata

    // Aura tipini hashtag olarak ekle
    if (!hashtags.includes(auraType)) {
      hashtags.push(auraType);
    }

    // Galeriye eklemek için veriyi hazırla
    const galleryData = {
      id: auraId,
      userId: userId,
      username: auraData.username,
      auraType: auraType, // Kontrol edilmiş auraType kullan
      title: auraData.title,
      createdAt: auraData.createdAt,
      likes: 0,
      likedBy: [],
      description: description,
      hashtags: hashtags
    };

    // Mevcut galeri paylaşımlarını al
    const existingShares = JSON.parse(localStorage.getItem('auralize_shared_auras') || '[]');

    // Yeni paylaşımı ekle
    existingShares.push(galleryData);

    // Güncellenmiş paylaşımları kaydet
    localStorage.setItem('auralize_shared_auras', JSON.stringify(existingShares));

    // Aurayı paylaşıldı olarak işaretle
    auraData.isShared = true;

    // localStorage'daki versiyonu da güncelle
    localStorage.setItem(`auralize_aura_${auraId}`, JSON.stringify({...auraData, auraType: auraType}));

    // LLaMA hikayesini ve içgörüleri de ayrı dosyalarda sakla
    localStorage.setItem(`auralize_story_${auraId}`, auraData.story);
    localStorage.setItem(`auralize_strengths_${auraId}`, auraData.strengths);
    localStorage.setItem(`auralize_potential_${auraId}`, auraData.potential);
    localStorage.setItem(`auralize_thinking_${auraId}`, auraData.thinkingStyle);

    // Paylaşım durumunu işaretle
    localStorage.setItem(`auralize_shared_${userId}_${auraId}`, 'true');

    return true;
  } catch (error) {
    console.error('[AuraDataService] Aura paylaşılırken hata:', error);
    return false;
  }
};
